TypeScript example (pagination + migration hint):

const client = new RedwoodClient({ apiKey: process.env.RW_KEY, tenantId });
const page = await client.listEvents({ cursor: legacyCursor })
if (page.migration_hint) console.warn("Cursor migration available: run redwood-cursor-migrate")
await page.items.forEach(handleEvent)

// resume streaming with de-dup guarantees
const stream = client.streamEvents({ cursor: page.cursor })
for await (const chunk of stream) handleChunk(chunk)

Go example (robust resume + idempotency):

client := redwood.NewClient(redwood.Config{APIKey: os.Getenv("RW_KEY"), TenantID: tenant})
stream, err := client.ResumeStream(ctx, &redwood.ResumeParams{Cursor: cursor})
if err != nil { log.Fatal(err) }
for stream.Next() { evt := stream.Event(); process(evt) }

// SDK exposes ResumeOptions{MaxRetries: 4, BackoffMs: 200} and emits telemetry events to tracing backend
